import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    static class Matrix {
        int[][] A;
        int N;

        Matrix(int size) {
            A = new int[size][size];
            N = size;
        }

        Matrix multiply(Matrix B) {
            Matrix C = new Matrix(N);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    long sum = 0;
                    for (int k = 0; k < N; k++) {
                        sum += (long) A[i][k] * B.A[k][j];
                    }
                    C.A[i][j] = (int) (sum % MOD);
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long K = sc.nextLong();

        int cnt = 0;
        long[] dig = new long[70];

        while (N != 0) {
            dig[cnt++] = N % K;
            N /= K;
        }

        int maxK = (int) K;
        Matrix[][] A = new Matrix[cnt][maxK];
        Matrix[][] sum = new Matrix[cnt][maxK];
        Matrix[][] suf = new Matrix[cnt][maxK];

        for (int i = 0; i < cnt; i++) {
            for (int j = 0; j < maxK; j++) {
                A[i][j] = new Matrix(maxK);
            }
        }

        // Initialize A[0][i]
        for (int i = 0; i < maxK; i++) {
            for (int j = 0; j < maxK; j++) {
                A[0][i].A[j][j] = 0;
            }
            for (int j = 0; j < maxK; j++) {
                A[0][i].A[j][j] = 1;
            }
            A[0][i].A[i][i] = 1;
            A[0][i].A[maxK - 1][i] = 1;
            A[0][i].N = maxK;
        }

        // Initialize sum[0][i]
        for (int i = 0; i < maxK; i++) {
            sum[0][i] = A[0][i];
        }

        // Initialize suf[0][i]
        for (int i = 0; i < maxK; i++) {
            suf[0][i] = A[0][i];
        }

        // Build sum and suf for i >= 1
        for (int i = 1; i < cnt; i++) {
            // A[i][0]
            A[i][0] = suf[i - 1][0];

            // A[i][j]
            for (int j = 1; j < maxK; j++) {
                A[i][j] = suf[i - 1][j].multiply(sum[i - 1][j - 1]);
            }

            // sum[i][j]
            sum[i][0] = A[i][0];
            for (int j = 1; j < maxK; j++) {
                sum[i][j] = sum[i][j - 1].multiply(A[i][j]);
            }

            // suf[i][j]
            for (int j = maxK - 2; j >= 0; j--) {
                suf[i][j] = A[i][j].multiply(suf[i][j + 1]);
            }
        }

        // Initialize answer matrix
        Matrix ans = new Matrix(maxK);
        ans.N = maxK;
        ans.A[0][maxK - 1] = 1;

        // Multiply ans by sum[cnt-1][dig[cnt-1] - 1]
        int last = (int) dig[cnt - 1];
        ans = ans.multiply(sum[cnt - 1][last - 1]);

        // Loop through remaining digits
        for (int i = cnt - 2; i >= 0; i--) {
            int limit = (int) dig[i];
            for (int j = 0; j < limit; j++) {
                ans = ans.multiply(A[i][(j + last) % maxK]);
            }
            last += limit;
        }

        long res = 0;
        for (int i = 0; i <= maxK; i++) {
            res += ans.A[0][i];
        }
        System.out.println(res % MOD);
        sc.close();
    }
}
